const input=$json??{};
const dealId=input.deal_id??null; const leadId=input.lead_id??null; const propertyId=input.property_id??null;
const status=String(input.status??'').toLowerCase(); const dispatchMode=String(input.dispatch_mode??input.channel??'').toLowerCase();
const dnc=Boolean(input.dnc??input.do_not_contact??false); const blockers=Array.isArray(input.blockers)?input.blockers:[];
const idempotencyKey=String(input.idempotency_key??'').trim();
const phone=String(input.recipient_phone??input.seller_phone??'').trim(); const email=String(input.recipient_email??input.seller_email??'').trim();
const message=String(input.generated_message??input.message??'').trim();
let route='human_review'; let nextWorkflow='WF-347'; let reason='Provider dispatch requires review.';
if(dnc){route='blocked';nextWorkflow='WF-126';reason='DNC protection prevents provider dispatch.';}
else if(blockers.length){route='blocked';nextWorkflow='WF-126';reason='Active blocker prevents provider dispatch.';}
else if(!dealId||!leadId||!propertyId){route='incomplete';nextWorkflow='WF-347';reason='Deal identity is incomplete.';}
else if(!idempotencyKey){route='invalid_idempotency';nextWorkflow='WF-347';reason='Dispatch idempotency key is missing.';}
else if(!message){route='message_missing';nextWorkflow='WF-347';reason='Generated seller message is missing.';}
else if(dispatchMode==='sms'&&!phone){route='recipient_missing';nextWorkflow='WF-347';reason='SMS recipient is missing.';}
else if(dispatchMode==='email'&&!email){route='recipient_missing';nextWorkflow='WF-347';reason='Email recipient is missing.';}
else if(!['sms','email'].includes(dispatchMode)){route='unsupported_channel';nextWorkflow='WF-347';reason='Communication channel is not supported.';}
else if(status!=='message_ready'){route='not_authorized';nextWorkflow='WF-347';reason='Message is not authorized for autonomous dispatch.';}
else{route='dispatch_ready';nextWorkflow='WF-349';reason='Provider dispatch package passed safety and identity checks.';}
const dispatchPackage={provider_agnostic:true,channel:dispatchMode,recipient:dispatchMode==='sms'?phone:email,message,idempotency_key:idempotencyKey,deal_id:dealId,lead_id:leadId,property_id:propertyId};
const activity={activity_type:'provider_dispatch_controller',subject:'WF-348 '+(dealId??'unknown-deal'),deal_id:dealId,lead_id:leadId,property_id:propertyId,route,channel:dispatchMode,idempotency_key:idempotencyKey,provider_agnostic:true,dnc,blockers,dispatch_package:dispatchPackage,reason,next_workflow:nextWorkflow};
return [{json:{...input,wf_id:'WF-348',route,next_workflow:nextWorkflow,dispatch_package:dispatchPackage,reason,crm_activity:activity,evaluated_at:new Date().toISOString()}}];
